const escapeHtml = (v) => String(v)
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;");

export function buildContractHtml() {
  let html = "";
  for (const sec of CONTRACT_SECTIONS) {
    html += `<h2 style="font-size:17px;color:#17151b;margin:22px 0 8px;">${escapeHtml(sec.heading)}</h2>`;
    let inList = false;
    for (const b of sec.blocks) {
      if (b.type === "h") {
        if (inList) { html += "</ul>"; inList = false; }
        html += `<h3 style="font-size:15px;color:#17151b;margin:16px 0 6px;">${escapeHtml(b.text)}</h3>`;
      } else if (b.type === "li") {
        if (!inList) { html += '<ul style="margin:0 0 10px 18px;padding:0;">'; inList = true; }
        html += `<li style="margin-bottom:6px;color:#17151b;font-size:14px;">${escapeHtml(b.text)}</li>`;
      } else if (b.type === "table") {
        if (inList) { html += "</ul>"; inList = false; }
        html += '<table style="width:100%;border-collapse:collapse;margin:8px 0 12px;font-size:13px;">';
        for (const line of b.lines) {
          html += `<tr><td style="border:1px solid #e4e2ea;padding:6px 10px;color:#17151b;">${escapeHtml(line)}</td></tr>`;
        }
        html += "</table>";
      } else {
        if (inList) { html += "</ul>"; inList = false; }
        html += `<p style="margin:0 0 8px;color:#17151b;font-size:14px;line-height:1.55;">${escapeHtml(b.text)}</p>`;
      }
    }
    if (inList) html += "</ul>";
  }
  return html;
}

export function buildContractText() {
  let out = CONTRACT_TITLE + "\n" + CONTRACT_SUBTITLE + "\n";
  for (const sec of CONTRACT_SECTIONS) {
    out += "\n\n" + sec.heading.toUpperCase() + "\n" + "=".repeat(sec.heading.length) + "\n";
    for (const b of sec.blocks) {
      if (b.type === "h") out += "\n" + b.text + "\n";
      else if (b.type === "li") out += "  - " + b.text + "\n";
      else if (b.type === "table") out += b.lines.map((l) => "  | " + l).join("\n") + "\n";
      else out += "\n" + b.text + "\n";
    }
  }
  return out;
}
